<?php
if (!defined("SUAVE_RAIZ")) { http_response_code(404); exit; } use Suave\Interfaz as V;use Suave\Numeros as N;
$closing=new Suave\Cierres($db);$s=(new Suave\Conciliador($db))->summary($month);$historyId=(int)($_GET['cierre_id']??0);$historical=$historyId>0;
$snapshot=$historical?$closing->historical($historyId):($period['estado']==='Revisado'?$closing->historical((int)$period['cierre_id']):null);
$displayMonth=$snapshot['mes']??$month;$reviewed=$snapshot!==null;$blockers=$snapshot?[]:$closing->blockers($s);$rows=$snapshot['resumen']??array_values($s['branches']);$totals=$snapshot['totales']??['suave'=>$s['own'],'excel'=>$s['received'],'diferencia'=>$s['received']===null?null:$s['own']-$s['received'],'validado'=>$s['validated']];
$panel=(string)($_GET['panel']??'');$posted=$_SERVER['REQUEST_METHOD']==='POST';$checked=fn($key,$default=false)=>$posted?!empty($_POST[$key]):(bool)$default;
?>
<div class="page-heading"><div><h1>Cierre de <?=V::h(V::monthLabel($displayMonth))?></h1><p><?=$reviewed?'Expediente revisado · versión '.$snapshot['version']:'Resumen mensual, fuentes y condiciones para completar la revisión.'?></p></div><?=V::badge($reviewed?'Revisado':'Preliminar')?></div>
<?php if($historical):?><div class="notice">Consulta histórica del cierre v<?=$snapshot['version']?>. Su contenido corresponde a <?=V::h($snapshot['generado_en'])?>. <?=$w->link('Volver al cierre actual','cierre',['mes'=>$displayMonth],'text-link')?></div><?php else:?>
<form method="get" class="filters"><?=V::hidden('p','cierre')?><?=V::input('Mes','mes',$month,'month',['required'=>true])?><button type="submit" class="button">Consultar</button></form><?php endif?>
<div class="metrics three"><article class="metric"><span>Notas SUAVE</span><strong><?=N::currency((int)$totals['suave'])?></strong></article><article class="metric"><span>Excel cliente</span><strong><?=$totals['excel']===null?'Sin reporte':N::currency((int)$totals['excel'])?></strong></article><article class="metric"><span>Importe validado</span><strong class="<?=$reviewed?'good-text':'warning-text'?>"><?=$totals['validado']===null?'Incompleto':N::currency((int)$totals['validado'])?></strong></article></div>
<?=$w->branchTable($rows,true)?>
<?php if($blockers):?><section class="notice warning"><strong>El cierre sigue preliminar</strong><ul><?php foreach($blockers as $reason):?><li><?=V::h($reason)?></li><?php endforeach?></ul></section><?php elseif($reviewed):?><p class="hint">Este expediente conserva sus notas, reporte, reglas y decisiones. Una reapertura no modifica esta versión histórica.</p><?php else:?><div class="notice success">Las condiciones de revisión están completas. Puedes marcar este cierre como revisado.</div><?php endif?>
<div class="action-row spread"><div class="action-row"><?=$w->link('Ver '.($snapshot?count(array_filter($snapshot['casos'],fn($c)=>$c['estado']==='Pendiente')):$s['pending']).' pendientes','conciliacion',['mes'=>$displayMonth,'estado'=>'Pendiente'])?><?php if(!$historical):?><?=$w->link('Datos del mes','cierre',['panel'=>'datos'])?><?=$w->link('Ver historial','cierre',['panel'=>'historial'])?><?php endif?></div>
<?php if(!$historical&&$period['estado']!=='Revisado'):?><form method="post"><?=V::protect('cierre_revisar')?><?=V::hidden('mes',$month)?><?=V::hidden('revision_periodo',$period['revision'])?><button class="button primary" type="submit" <?=$blockers?'disabled':''?>>Marcar revisado</button></form><?php elseif(!$historical):?><?=$w->link('Reabrir mes','cierre',['panel'=>'reabrir'])?><?php endif?></div>
<div class="section-block export-row"><h2><?=$reviewed?'Exportar revisado':'Exportar preliminar'?></h2><p class="hint">El archivo incluye las fuentes y el estado de la revisión. Su entrega al contador se realiza por el proceso habitual.</p><div class="action-row"><?=$w->link('Descargar PDF','exportar',['mes'=>$displayMonth,'formato'=>'pdf','cierre_id'=>$historical?$historyId:($reviewed?$period['cierre_id']:null)],'button primary')?><?=$w->link('Descargar Excel','exportar',['mes'=>$displayMonth,'formato'=>'xlsx','cierre_id'=>$historical?$historyId:($reviewed?$period['cierre_id']:null)])?></div></div>
<?php if(!$historical&&$panel==='datos'):
$scope=$posted?(is_array($_POST['alcance']??null)?$_POST['alcance']:[]):$params['sucursales'];$zero=$posted?(is_array($_POST['sin_movimiento']??null)?$_POST['sin_movimiento']:[]):$params['sin_movimiento'];
?>
<section class="section-block" id="datos-mes"><div class="section-heading"><h2>Datos del mes</h2><?=$w->link('Cerrar panel','cierre',[],'text-link')?></div>
<?php if($period['estado']==='Revisado'):?><p>Reabre el mes con un motivo antes de modificar sus reglas o cobertura.</p><?php else:?>
<form method="post" data-dirty><?=V::protect('parametros_guardar')?><?=V::hidden('mes',$month)?><?=V::hidden('revision_periodo',V::value('revision_periodo',$period['revision']))?>
<div class="form-grid three"><?=V::input('Fecha límite acordada (opcional)','fecha_limite',V::value('fecha_limite',$params['fecha_limite']),'date')?><?=V::input('Número de sucursales esperadas *','numero_sucursales',V::value('numero_sucursales',$params['numero_sucursales']),'number',['min'=>1,'max'=>100,'required'=>true])?><?=V::select('Decimales permitidos en cantidades','decimales_cantidad',[0=>'Cantidades enteras',1=>'Hasta 1 decimal',2=>'Hasta 2 decimales',3=>'Hasta 3 decimales'],V::value('decimales_cantidad',$params['decimales_cantidad']))?></div>
<?=V::check('permitir_precio_cero','La panadería permite precio cero en las entregas.',$checked('permitir_precio_cero',$params['permitir_precio_cero']))?>
<?=V::check('folio_compartido','Comprobé que existe un folio compartido en la nota y el reporte del cliente.',$checked('folio_compartido',$params['folio_compartido']))?>
<?=V::input('Documentos usados para comprobar el folio compartido','folio_evidencia',V::value('folio_evidencia',$params['folio_evidencia']??''),'text',['maxlength'=>2000,'placeholder'=>'Indica qué fuentes comprobaste; déjalo vacío si aún no se ha confirmado.'])?>
<h3>Sucursales incluidas en el mes</h3><p class="hint">Confirma el alcance real. Marca Sin movimiento solo si no hubo entregas ni importes en esa sucursal.</p>
<?php if(!$allBranches):?><p>Primero registra las sucursales en Catálogos.</p><?php else:?><div class="table-wrap"><table><thead><tr><th>Sucursal</th><th>Incluir en el alcance</th><th>Sin movimiento comprobado</th></tr></thead><tbody><?php foreach($allBranches as $b):?><tr><td><?=V::h($b['codigo'].' · '.$b['nombre'])?></td><td><?=V::check('alcance[]','Incluir '. $b['codigo'],in_array($b['codigo'],$scope,true),$b['codigo'])?></td><td><?=V::check('sin_movimiento[]','Sin movimiento en '.$b['codigo'],in_array($b['codigo'],$zero,true),$b['codigo'])?></td></tr><?php endforeach?></tbody></table></div><?php endif?>
<?=V::check('cobertura_confirmada','Confirmé que el alcance y la cobertura del reporte corresponden al mes completo.',$checked('cobertura_confirmada',$params['cobertura_confirmada']))?>
<?=V::check('reglas_confirmadas','Confirmé con la panadería las reglas de cantidad, precio y revisión de este periodo.',$checked('reglas_confirmadas',$params['reglas_confirmadas']))?>
<?php if($s['drafts']):?><div class="notice"><strong>Borradores excluidos: <?=count($s['drafts'])?></strong><p><?=V::h(implode(', ',array_column($s['drafts'],'referencia')))?></p><?=V::check('borradores_comprobados','Revisé estos borradores y confirmé que ninguno corresponde a una entrega real pendiente de registrar.',$checked('borradores_comprobados',!array_filter($s['drafts'],fn($n)=>(int)($params['borradores_revisados'][(string)$n['entrega_id']]??0)!==(int)$n['numero'])))?></div><?php endif?>
<?=V::textarea('Observaciones y reglas acordadas','observaciones',(string)V::value('observaciones',$params['observaciones']))?>
<div class="action-row"><button class="button primary" type="submit">Guardar datos</button><?=$w->link('Cancelar','cierre')?></div></form><?php endif?></section>
<?php endif?>
<?php if(!$historical&&$panel==='reabrir'&&$period['estado']==='Revisado'):?><section class="section-block"><h2>Reabrir mes</h2><p>La versión revisada se conservará. El mes volverá a preliminar para incorporar cambios y preparar otra versión.</p><form method="post" data-dirty><?=V::protect('cierre_reabrir')?><?=V::hidden('mes',$month)?><?=V::hidden('cierre_id',$period['cierre_id'])?><?=V::textarea('Motivo de reapertura *','motivo',(string)V::value('motivo',''),true)?><div class="action-row"><button class="button primary" type="submit">Confirmar reapertura</button><?=$w->link('Cancelar','cierre')?></div></form></section><?php endif?>
<?php if(!$historical&&$panel==='historial'):?><section class="section-block"><h2>Historial de cierres</h2><div class="table-wrap"><table><thead><tr><th>Versión</th><th>Fecha de revisión</th><th>Reaperturas</th><th>Consulta</th></tr></thead><tbody><?php $history=$db->all('SELECT c.*,(SELECT COUNT(*) FROM reaperturas r WHERE r.cierre_id=c.id) AS reaperturas FROM cierres c WHERE c.mes=? ORDER BY c.numero DESC',[$month]);foreach($history as $item):?><tr><td>v<?=$item['numero']?></td><td><?=V::h($item['creado_en'])?></td><td><?=$item['reaperturas']?></td><td><?=$w->link('Consultar expediente','cierre',['cierre_id'=>$item['id']],'text-link')?></td></tr><?php endforeach?><?php if(!$history):?><tr><td colspan="4" class="empty-cell">Todavía no hay cierres revisados.</td></tr><?php endif?></tbody></table></div></section><?php endif?>
